public class Processor {
    private DataStore store;

    public Processor(DataStore store) {
        this.store = store;
    }

    public void process(String id) {
        store.addRecord(id);
    }

    public void handle(int code) {
        int result = store.fetchRecord(code);
        System.out.println("Result: " + result);
    }
}

public class DataStore {
    public void addRecord(String id, String data) {
        System.out.println("Record added: " + id);
    }

    public String retrieveRecord(int id) {
        return "Record " + id;
    }
}

